<template>
  <sf-sheet class="sf-premium-paywall" :class="{'is-compact':compact}" :open="open" :title="wall.headline.replace(/\n/g,' ')" contained :resizable="false" :busy="processing" content-class="sf-premium-paywall__panel" @input="$emit('close')">
    <div class="sf-premium-paywall__brand"><sf-icon name="membership" :size="17"/><span>SunnyFit <b>Premium</b></span></div>
    <div class="sf-premium-paywall__story">
      <sf-paywall-artwork :kind="wall.artwork"/>
      <div v-if="wall.resource.name" class="sf-premium-paywall__context"><span class="sf-premium-paywall__context-dot"/>{{ wall.resource.name }}<small v-if="wall.resource.savedDraft">Message saved</small><small v-else-if="wall.resource.detail">{{ wall.resource.detail }}</small></div>
      <h1>{{ wall.headline }}</h1><p class="sf-premium-paywall__subtitle">{{ wall.subtitle }}</p>
      <ul class="sf-premium-paywall__benefits"><li v-for="(benefit,index) in wall.benefits" :key="benefit.id" :class="{'is-focus':index===0}"><span><sf-icon :name="benefit.icon" :size="16"/></span>{{ benefit.title }}</li></ul>
      <section v-if="wall.offers.length" class="sf-premium-paywall__plans" aria-label="Premium plans"><div class="sf-premium-paywall__plan-heading"><h2>Choose your plan</h2></div><div class="context-purchase-offers" role="radiogroup" aria-label="Subscription billing period"><button v-for="offer in wall.offers" :key="offer.offerId" type="button" role="radio" :aria-checked="selectedId===offer.offerId?'true':'false'" :disabled="processing" :data-offer-id="offer.offerId" :data-sku-id="offer.sku.id" @click="$emit('select',offer)"><span class="sf-premium-paywall__period"><i/><strong>{{ offer.sku.billingPeriod==='annual'?'Yearly':'Monthly' }}</strong></span><span class="sf-premium-paywall__price"><b>{{ money(offer.sku.priceCents,offer.sku.currency) }}</b><small>/ {{ offer.sku.billingPeriod==='annual'?'year':'month' }}</small></span><small v-if="offer.trialDays" class="sf-premium-paywall__offer-badge">{{ offer.trialDays }} days free</small><small v-else-if="saving(offer)>0" class="sf-premium-paywall__saving">Save {{ saving(offer) }}%</small><small v-else class="sf-premium-paywall__regular">Billed monthly</small></button></div></section>
      <div v-else class="sf-premium-paywall__unavailable" role="status"><strong>Plans aren’t available right now.</strong><p>Your activity is saved. Try loading plans again.</p><button type="button" @click="$emit('reload')">Try again</button></div>
      <details class="sf-premium-paywall__all-benefits" @toggle="$emit('details',$event.target.open)"><summary>All Premium benefits<sf-icon name="plus" :size="13"/></summary><ul><li v-for="benefit in wall.fullBenefits" :key="benefit"><sf-icon name="check" :size="13"/>{{ benefit }}</li></ul></details>
      <p v-if="feedback" class="sf-premium-paywall__feedback" role="status">{{ feedback }}</p>
    </div>
    <template #footer><sf-button class="sf-premium-paywall__continue" :disabled="!selectedOffer||processing" @click="$emit('purchase',selectedOffer)">{{ processing?processingLabel:selectedOffer?selectedOffer.cta:'Plans unavailable' }}</sf-button><p class="sf-premium-paywall__disclosure">{{ disclosure }}</p><div class="sf-premium-paywall__links"><button type="button" :disabled="processing" @click="$emit('restore')">Restore purchases</button><a :href="termsUrl" target="_blank" rel="noopener noreferrer">Terms</a><a :href="privacyUrl" target="_blank" rel="noopener noreferrer">Privacy</a></div></template>
  </sf-sheet>
</template>
<script>
import SfSheet from './SfSheet'
import SfButton from './SfButton'
import SfIcon from './SfIcon'
import SfPaywallArtwork from './SfPaywallArtwork'
export default {
  name:'SfPaywall',components:{SfSheet,SfButton,SfIcon,SfPaywallArtwork},props:{open:Boolean,wall:{type:Object,required:true},selectedId:String,processing:Boolean,processingLabel:{type:String,default:'Confirming purchase…'},feedback:String,disclosure:String,termsUrl:String,privacyUrl:String},
  data(){return {compact:false}},
  mounted(){this.$nextTick(()=>{const panel=this.$el.querySelector('.sf-modal');if(!panel)return;const update=()=>{this.compact=panel.clientHeight<=650};update();if(typeof ResizeObserver!=='undefined'){this.wallObserver=new ResizeObserver(update);this.wallObserver.observe(panel)}})},
  beforeDestroy(){if(this.wallObserver)this.wallObserver.disconnect()},
  computed:{selectedOffer(){return this.wall.offers.find(offer=>offer.offerId===this.selectedId)}},
  methods:{money(cents,currency){return new Intl.NumberFormat('en-US',{style:'currency',currency}).format(cents/100)},saving(offer){const monthly=this.wall.offers.find(item=>item.sku.billingPeriod==='monthly'&&item.sku.currency===offer.sku.currency);return offer.sku.billingPeriod==='annual'&&monthly&&monthly.sku.priceCents>0?Math.max(0,Math.floor((1-offer.sku.priceCents/(12*monthly.sku.priceCents))*100)):0}}
}
</script>
